/* @lc app=leetcode id=2265 lang=kotlin */
class Solution { fun averageOfSubtree(root: TreeNode?): Int = IntArray(1).let { a -> kotlin.DeepRecursiveFunction<TreeNode?, Pair<Int, Int>> { n -> if (n == null) 0 to 0 else callRecursive(n.left).let { l -> callRecursive(n.right).let { r -> (l.first + r.first + n.`val` to l.second + r.second + 1).also { if (it.first / it.second == n.`val`) a[0]++ } } } }.invoke(root).let { a[0] } } }